function ensurePaymentLocations(){if(!ops.inv)return[];if(window.RayoPaymentLocations)return RayoPaymentLocations.all(ops.inv);return A(Array.isArray(ops.inv.paymentLocations)?ops.inv.paymentLocations:ops.inv.settings?.paymentLocations).map((x,i)=>typeof x==='string'?{id:`PAYLOC-${String(i+1).padStart(3,'0')}`,name:x,isActive:true}:({...x}))}
function paymentLocations(){return ensurePaymentLocations().filter(x=>x.isActive!==false)}
function paymentLocationName(id,snapshot=''){return snapshot||ensurePaymentLocations().find(x=>x.id===id)?.name||'—'}
function paymentLocationOptions(selected='',snapshot=''){let a=paymentLocations().slice();if(selected&&!a.some(x=>x.id===selected))a.unshift({id:selected,name:snapshot||'محل پرداخت قبلی'});return `<option value="">— انتخاب کنید —</option>`+a.map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.name)}</option>`).join('')}
