function linkedPayments(invoiceId){return A(ops.inv?.supplierPayments).filter(p=>p.status!=='void'&&p.invoiceId===invoiceId).reduce((a,p)=>a+supplierPaymentSign(p)*N(p.amount),0)}
function invoicePaid(x){return N(x?.paidAmount)+linkedPayments(x?.id)}
function invoiceStatus(x){const t=invoiceTotal(x),p=invoicePaid(x);if(p<=0)return 'پرداخت نشده';if(p+0.5<t)return 'پرداخت جزئی';if(p<=t+0.5)return 'تسویه شده';return 'بستانکار/پیش‌پرداخت'}
function settlementCode(x){const t=invoiceTotal(x),p=invoicePaid(x);if(p<=0)return'unpaid';if(p+0.5<t)return'partial';return'paid'}
function supplierAccount(supplierId){const invoices=A(ops.inv?.purchaseInvoices).filter(x=>x.status!=='void'&&(x.supplierId===supplierId||x.supplierCode===supplierId));const purchases=invoices.reduce((a,x)=>a+invoiceTotal(x),0);const invoiceInitial=invoices.reduce((a,x)=>a+N(x.paidAmount),0);const payments=A(ops.inv?.supplierPayments).filter(x=>x.status!=='void'&&(x.supplierId===supplierId||x.supplierCode===supplierId)).reduce((a,x)=>a+supplierPaymentSign(x)*N(x.amount),0);const paid=invoiceInitial+payments;return{invoices,purchases,paid,balance:purchases-paid}}
function tracked(id){return A(ops.inv?.trackedIngredients).find(x=>x.ingredientId===id)}
function eventDate(sp,line){return D(line?.date||sp?.to||sp?.date||sp?.from||'')}
function consumptionFromSales(ingredientId,baseDate,targetDate){let q=0;for(const sp of A(ops.inv?.salesPeriods)){if(sp.status==='void'||sp.isArchived)continue;for(const l of A(sp.lines)){const dt=eventDate(sp,l);if(!dt||!after(dt,baseDate)||!onOrBefore(dt,targetDate))continue;const qty=N(l.quantity);for(const r of RayoIngredientMath.recipeAt(ops.pricing,l.menuItemId,dt))if(r.ingredientId===ingredientId)q+=RayoIngredientMath.grossQuantity(ingredient(ingredientId),r,qty)}}return q}
function wasteIngredientQty(w,ingredientId){const qty=N(w.quantity);if(w.type==='ingredient')return w.itemId===ingredientId?qty:0;if(w.type==='menu'){const r=RayoIngredientMath.recipeAt(ops.pricing,w.itemId,D(w.date)).find(x=>x.ingredientId===ingredientId);return r?RayoIngredientMath.grossQuantity(ingredient(ingredientId),r,qty):0}return 0}
function wasteFromRecords(ingredientId,baseDate,targetDate){let q=0;for(const w of A(ops.inv?.wasteRecords)){const dt=D(w.date);if(w.status==='void'||w.isArchived||['ردشده','در انتظار بررسی'].includes(w.reviewStatus)||!dt||!after(dt,baseDate)||!onOrBefore(dt,targetDate))continue;q+=wasteIngredientQty(w,ingredientId)}return q}
function receiptsAfter(ingredientId,baseDate,targetDate){return A(ops.inv?.stockReceipts).filter(r=>receiptPosted(r)&&r.ingredientId===ingredientId&&after(D(r.date),baseDate)&&onOrBefore(D(r.date),targetDate)).reduce((a,r)=>a+N(r.quantity),0)}
function receiptUnitCost(r){const stockQty=N(r?.quantity),purchaseQty=N(r?.purchaseQuantity),price=N(r?.unitPrice);if(stockQty>0&&purchaseQty>0&&price>0)return purchaseQty*price/stockQty;return 0}
function receiptPosted(r){return !r?.status||r.status==='received'||r.status==='posted'}
function periodPurchaseCost(ingredientId,baseDate,targetDate){
  const rows=A(ops.inv?.stockReceipts).filter(r=>receiptPosted(r)&&r.ingredientId===ingredientId&&after(D(r.date),baseDate)&&onOrBefore(D(r.date),targetDate)&&N(r.quantity)>0&&receiptUnitCost(r)>0);
  const purchasedQty=rows.reduce((a,r)=>a+N(r.quantity),0);
  const purchaseValueToman=rows.reduce((a,r)=>a+N(r.quantity)*receiptUnitCost(r),0);
  if(purchasedQty>0&&purchaseValueToman>0)return{unitCost:purchaseValueToman/purchasedQty,purchasedQty,purchaseValueToman,source:'میانگین موزون خرید دوره',receiptCount:rows.length};
  const previous=A(ops.inv?.stockReceipts).filter(r=>receiptPosted(r)&&r.ingredientId===ingredientId&&D(r.date)&&(!baseDate||dateCmp(D(r.date),baseDate)<=0)&&receiptUnitCost(r)>0).sort((a,b)=>dateCmp(D(b.date),D(a.date)))[0];
  if(previous)return{unitCost:receiptUnitCost(previous),purchasedQty:0,purchaseValueToman:0,source:'آخرین خرید قبل از دوره',receiptCount:0,referenceDate:D(previous.date)};
  return{unitCost:RayoIngredientMath.grossCost(ingredient(ingredientId),ops.pricing),purchasedQty:0,purchaseValueToman:0,source:'آخرین قیمت ثبت‌شده ماده',receiptCount:0};
}
function previousCount(ingredientId,targetDate,excludeId=''){const candidates=[];for(const st of A(ops.inv?.stocktakes)){if(st.id===excludeId)continue;const dt=D(st.date);if(!dt||dateCmp(dt,targetDate)>=0)continue;for(const l of A(st.lines))if(l.ingredientId===ingredientId)candidates.push({date:dt,actual:N(l.actual),stocktakeId:st.id,line:l})}candidates.sort((a,b)=>dateCmp(b.date,a.date));return candidates[0]||null}
function latestCountAtOrBefore(ingredientId,targetDate){const candidates=[];for(const st of A(ops.inv?.stocktakes)){const dt=D(st.date);if(!dt||dateCmp(dt,targetDate)>0)continue;for(const l of A(st.lines))if(l.ingredientId===ingredientId)candidates.push({date:dt,actual:N(l.actual),stocktakeId:st.id,line:l})}candidates.sort((a,b)=>dateCmp(b.date,a.date));return candidates[0]||null}
function baselineFor(ingredientId,targetDate,excludeId='',allowSame=false){const count=allowSame?latestCountAtOrBefore(ingredientId,targetDate):previousCount(ingredientId,targetDate,excludeId);if(count)return{date:count.date,quantity:count.actual,source:'شمارش قبلی'};const c=tracked(ingredientId)||{};return{date:D(c.initialStockDate||''),quantity:N(c.initialStock),source:'موجودی اولیه'}}
function positionAt(ingredientId,targetDate=today(),{excludeStocktakeId='',actual=null,allowSameBaseline=true}={}){const base=baselineFor(ingredientId,targetDate,excludeStocktakeId,allowSameBaseline&&actual===null),receipts=receiptsAfter(ingredientId,base.date,targetDate),sales=consumptionFromSales(ingredientId,base.date,targetDate),waste=wasteFromRecords(ingredientId,base.date,targetDate),beforeWaste=base.quantity+receipts-sales,expected=beforeWaste-waste,cost=periodPurchaseCost(ingredientId,base.date,targetDate),unitCost=cost.unitCost;const actualNum=actual===null?null:N(actual),gross=actualNum===null?null:actualNum-beforeWaste,variance=actualNum===null?null:actualNum-expected;return{ingredientId,date:targetDate,baseDate:base.date,baseQuantity:base.quantity,baseSource:base.source,receipts,salesConsumption:sales,recordedWaste:waste,expectedBeforeWaste:beforeWaste,expected,actual:actualNum,grossVariance:gross,variance,unitCost,periodUnitCostToman:unitCost,periodPurchaseQuantity:cost.purchasedQty,periodPurchaseValueToman:cost.purchaseValueToman,unitCostSource:cost.source,unitCostReferenceDate:cost.referenceDate||'',varianceValueToman:variance===null?null:variance*unitCost,lossValueToman:variance!==null&&variance<0?-variance*unitCost:0}}
function currentPosition(ingredientId,target=today()){const latest=latestCountAtOrBefore(ingredientId,target);if(latest){const baseDate=latest.date,receipts=receiptsAfter(ingredientId,baseDate,target),sales=consumptionFromSales(ingredientId,baseDate,target),waste=wasteFromRecords(ingredientId,baseDate,target),unitCost=RayoIngredientMath.grossCost(ingredient(ingredientId),ops.pricing);const current=latest.actual+receipts-sales-waste;return{ingredientId,date:target,baseDate,baseQuantity:latest.actual,baseSource:'آخرین شمارش',receipts,salesConsumption:sales,recordedWaste:waste,current,unitCost,value:current*unitCost,lastCount:latest}}const p=positionAt(ingredientId,target,{allowSameBaseline:false});return{...p,current:p.expected,value:p.expected*p.unitCost,lastCount:null}}
function wasteValue(w){if(w.type==='ingredient')return N(w.quantity)*RayoIngredientMath.grossCost(ingredient(w.itemId),ops.pricing);return N(w.quantity)*menuUnitCost(w.itemId)}
function ensureTrackedDefaults(){for(const ing of A(ops.pricing?.ingredients)){let t=tracked(ing.id);if(!t){t={id:id('TRACK'),ingredientId:ing.id,enabled:false,priority:'عادی',initialStock:0,initialStockDate:'',reorderPoint:0,targetStock:0,supplierId:'',notes:''};ops.inv.trackedIngredients.push(t)}else{t.priority=t.priority||'عادی';t.initialStock=N(t.initialStock);t.reorderPoint=N(t.reorderPoint);t.targetStock=N(t.targetStock)}}}
