function pane(){return corePane(ops.tab)}
function overviewPane(){const q=ops.filters.stockSearch.toLowerCase(),rows=A(ops.pricing.ingredients).filter(i=>i.status!=='غیرفعال').map(i=>{const c=tracked(i.id)||{},p=currentPosition(i.id),rp=N(c.reorderPoint),target=N(c.targetStock)||rp*2,order=Math.max(0,target-p.current);return{i,c,p,rp,target,order,s:supplier(c.supplierId)}}).filter(x=>(!q||(`${x.i.code||''} ${x.i.name||''}`).toLowerCase().includes(q))&&(!ops.filters.stockPriority||x.c.priority===ops.filters.stockPriority)&&(!ops.filters.stockOrderOnly||x.rp>0&&x.p.current<=x.rp));const value=rows.reduce((a,x)=>a+x.p.value,0),need=rows.filter(x=>x.rp>0&&x.p.current<=x.rp).length,important=rows.filter(x=>x.c.priority==='بالا').length;return `<div class="grid grid-3"><div class="card kpi"><div class="label">ارزش موجودی قابل محاسبه</div><div class="value">${F(value)}</div><div class="sub">تومان</div></div><div class="card kpi"><div class="label">نیازمند سفارش</div><div class="value">${F(need)}</div></div><div class="card kpi"><div class="label">مواد با اهمیت بالا</div><div class="value">${F(important)}</div></div></div><div class="card"><div class="toolbar"><div class="field"><label>جست‌وجو</label><input value="${E(ops.filters.stockSearch)}" oninput="ops.filters.stockSearch=this.value;renderView()" placeholder="نام یا کد ماده"></div><div class="field"><label>اهمیت</label><select onchange="ops.filters.stockPriority=this.value;renderView()"><option value="">همه</option>${['بالا','متوسط','عادی'].map(x=>`<option ${ops.filters.stockPriority===x?'selected':''}>${x}</option>`).join('')}</select></div><label class="check-inline"><input type="checkbox" ${ops.filters.stockOrderOnly?'checked':''} onchange="ops.filters.stockOrderOnly=this.checked;renderView()"> فقط نیازمند سفارش</label></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>اهمیت</th><th>تأمین‌کننده</th><th>موجودی محاسباتی لحظه‌ای</th><th>واحد</th><th>ارزش موجودی</th><th>نقطه سفارش</th><th>پیشنهاد سفارش</th><th>آخرین شمارش</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr class="${x.rp>0&&x.p.current<=x.rp?'row-alert':''}"><td><b>${E(x.i.name)}</b><br><small class="muted">${E(x.i.code||'')}</small></td><td>${badge(x.c.priority||'عادی')}</td><td>${E(supplierName(x.s))}</td><td><b>${F(x.p.current,3)}</b></td><td>${E(x.i.recipeUnit||'واحد')}</td><td>${M(x.p.value)}</td><td>${x.rp?F(x.rp,3):'—'}</td><td>${x.order>0?`<span class="badge warn">${F(x.order,3)}</span>`:'—'}</td><td>${E(x.p.lastCount?.date||'ثبت نشده')}</td><td><button class="btn btn-sm" onclick="opsEditStockControl('${x.i.id}')">تنظیم موجودی/سفارش</button></td></tr>`).join('')||'<tr><td colspan="10" class="empty">ماده‌ای پیدا نشد.</td></tr>'}</tbody></table></div></div>`}
function invoicePane(){const edit=ops.editInvoiceId?A(ops.inv.purchaseInvoices).find(x=>x.id===ops.editInvoiceId):null;setTimeout(()=>{const box=$id('opInvLines');if(box&&!box.children.length){if(edit?.lines?.length)edit.lines.forEach(l=>opsAddInvoiceLine(l));else opsAddInvoiceLine()}},0);const rows=A(ops.inv.purchaseInvoices).filter(x=>x.status!=='void').slice().sort((a,b)=>dateCmp(D(b.date),D(a.date))),settlement=edit?.settlementStatus||settlementCode(edit||{});return `<div class="card"><div class="section-head"><h2>${edit?'ویرایش فاکتور خرید':'ثبت فاکتور خرید'}</h2>${edit?'<button class="btn" onclick="opsCancelInvoiceEdit()">انصراف از ویرایش</button>':''}</div><div class="ops-grid"><div class="field"><label>تاریخ فاکتور</label><input id="opInvDate" data-jalali="1" value="${E(edit?.date||today())}"></div><div class="field"><label>تأمین‌کننده</label><select id="opInvSup">${opts(ops.sup.suppliers,'id',s=>supplierName(s),edit?.supplierId||new URLSearchParams(location.search).get('supplier')||'')}</select></div><div class="field"><label>شماره فاکتور</label><input id="opInvNo" value="${E(edit?.number||'')}"></div><div class="field"><label>تخفیف / کسورات (تومان)</label><input id="opInvDiscount" type="number" value="${N(edit?.discount)}"></div><div class="field"><label>وضعیت تسویه</label><select id="opInvSettlement"><option value="unpaid" ${settlement==='unpaid'?'selected':''}>تسویه‌نشده</option><option value="partial" ${settlement==='partial'?'selected':''}>تسویه جزئی</option><option value="paid" ${settlement==='paid'?'selected':''}>تسویه‌شده</option></select></div><div class="field"><label>مبلغ پرداخت‌شده همین فاکتور (تومان)</label><input id="opInvPaid" type="number" value="${N(edit?.paidAmount)}"></div><div class="field"><label>نوع پرداخت</label><select id="opInvPayMethod"><option value="">—</option>${paymentMethods().map(x=>`<option ${x===edit?.paymentMethod?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>محل پرداخت</label><select id="opInvPayLocation">${paymentLocationOptions(edit?.paymentLocationId||'',edit?.paymentLocationNameSnapshot||'')}</select></div><div class="field full"><label>توضیحات</label><input id="opInvNotes" value="${E(edit?.notes||'')}"></div><div class="full"><div class="section-head"><h2>اقلام فاکتور</h2><button class="btn btn-sm" onclick="opsAddInvoiceLine()">+ ردیف</button></div><div id="opInvLines"></div><div class="hint">مقدار را بر اساس واحد خرید وارد کنید. در حالت «تسویه‌شده» مانده فاکتور به‌صورت خودکار در مبلغ پرداخت‌شده لحاظ می‌شود. برای پرداخت‌های بعدی از تب «پرداخت تأمین‌کننده» استفاده کنید.</div></div><div class="full"><button class="btn btn-primary" onclick="opsSaveInvoice()">${edit?'ذخیره تغییرات فاکتور':'ثبت فاکتور خرید (در انتظار دریافت انبار)'}</button></div></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>تأمین‌کننده</th><th>شماره</th><th>جمع فاکتور</th><th>پرداخت‌شده</th><th>روش / محل</th><th>وضعیت</th><th>مانده</th><th></th></tr></thead><tbody>${rows.map(x=>{const t=invoiceTotal(x),p=invoicePaid(x),bal=t-p;return`<tr><td>${E(x.date)}</td><td>${E(supplierName(x.supplierId))}</td><td>${E(x.number||'—')}</td><td>${M(t)}</td><td>${M(p)}</td><td>${E(x.paymentMethod||'—')}<br><small class="muted">${E(paymentLocationName(x.paymentLocationId,x.paymentLocationNameSnapshot))}</small></td><td>${badge(invoiceStatus(x))}</td><td class="${bal>0?'danger-text':'positive'}">${M(Math.abs(bal))}${bal<0?' بستانکار':''}</td><td><button class="btn btn-sm" onclick="opsEditInvoice('${x.id}')">ویرایش</button> <button class="btn btn-danger btn-sm" onclick="opsDeleteInvoice('${x.id}')">حذف</button></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">فاکتوری ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}

function paymentPane(){const edit=ops.editPaymentId?A(ops.inv.supplierPayments).find(x=>x.id===ops.editPaymentId):null;const sid=edit?.supplierId||ops.paymentSupplierId||new URLSearchParams(location.search).get('supplier')||ops.sup.suppliers[0]?.id||'';const invs=A(ops.inv.purchaseInvoices).filter(x=>x.status!=='void'&&x.supplierId===sid);return `<div class="card"><div class="section-head"><h2>${edit?'ویرایش پرداخت':'ثبت پرداخت تأمین‌کننده'}</h2>${edit?'<button class="btn" onclick="opsCancelPaymentEdit()">انصراف</button>':''}</div><div class="ops-grid"><div class="field"><label>تأمین‌کننده</label><select id="opPaySup" onchange="ops.paymentSupplierId=this.value;renderView()">${opts(ops.sup.suppliers,'id',s=>supplierName(s),sid)}</select></div><div class="field"><label>فاکتور مربوط</label><select id="opPayInvoice"><option value="">پرداخت کلی / بدون فاکتور</option>${invs.map(x=>`<option value="${x.id}" ${x.id===edit?.invoiceId?'selected':''}>${E(x.date)} | ${E(x.number||x.id)} | مانده ${M(Math.max(0,invoiceTotal(x)-invoicePaid(x)))}</option>`).join('')}</select></div><div class="field"><label>تاریخ</label><input id="opPayDate" data-jalali="1" value="${E(edit?.date||today())}"></div><div class="field"><label>مبلغ (تومان)</label><input id="opPayAmount" type="number" value="${N(edit?.amount)}"></div><div class="field"><label>نوع پرداخت</label><select id="opPayMethod">${paymentMethods().map(x=>`<option ${x===(edit?.method||'کارت به کارت')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>محل پرداخت</label><select id="opPayLocation">${paymentLocationOptions(edit?.paymentLocationId||'',edit?.paymentLocationNameSnapshot||'')}</select></div><div class="field"><label>شماره پیگیری/چک</label><input id="opPayRef" value="${E(edit?.reference||'')}"></div><div class="field full"><label>شرح</label><input id="opPayNotes" value="${E(edit?.notes||'')}"></div><div class="full"><button class="btn btn-primary" onclick="opsSavePayment()">${edit?'ذخیره پرداخت':'ثبت پرداخت'}</button></div></div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>تأمین‌کننده</th><th>فاکتور</th><th>مبلغ</th><th>روش</th><th>محل پرداخت</th><th>پیگیری</th><th></th></tr></thead><tbody>${A(ops.inv.supplierPayments).filter(x=>x.status!=='void').slice().sort((a,b)=>dateCmp(D(b.date),D(a.date))).map(x=>{const iv=A(ops.inv.purchaseInvoices).find(i=>i.id===x.invoiceId);return`<tr><td>${E(x.date)}</td><td>${E(supplierName(x.supplierId))}</td><td>${E(iv?.number||'کلی')}</td><td>${M(x.amount)}</td><td>${E(x.method||'—')}</td><td>${E(paymentLocationName(x.paymentLocationId,x.paymentLocationNameSnapshot))}</td><td>${E(x.reference||'—')}</td><td><button class="btn btn-sm" onclick="opsEditPayment('${x.id}')">ویرایش</button> <button class="btn btn-danger btn-sm" onclick="opsDeletePayment('${x.id}')">حذف</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">پرداختی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}

function wastePane(){const rows=A(ops.inv.wasteRecords).slice().sort((a,b)=>dateCmp(D(b.date),D(a.date))),groups={};for(const w of rows){if(!w.invoiceNumber)continue;const k=`${D(w.date)}|${w.invoiceNumber}`;groups[k]=(groups[k]||0)+1}return `<div class="card"><div class="section-head"><h2>ثبت پرتی و ضایعات</h2></div><div class="ops-grid"><div class="field"><label>تاریخ</label><input id="opWasteDate" data-jalali="1" value="${today()}"></div><div class="field"><label>شماره فاکتور فروش سپیدز</label><input id="opWasteInvoice" placeholder="اختیاری؛ برای گروه‌بندی برگشتی‌ها"></div><div class="field"><label>نوع</label><select id="opWasteType" onchange="opsWasteType()"><option value="menu">آیتم منو</option><option value="ingredient">ماده اولیه</option></select></div><div class="field"><label>آیتم / ماده</label><select id="opWasteItem">${opts(ops.pricing.menuItems)}</select></div><div class="field"><label>تعداد / مقدار (واحد خرید قلم)</label><input id="opWasteQty" type="number" step="0.001"></div><div class="field"><label>علت مشخص است؟</label><select id="opWasteKnown"><option value="true">بله</option><option value="false">خیر / نیازمند بررسی</option></select></div><div class="field"><label>علت</label><select id="opWasteReason"><option>برگشت مشتری</option><option>سوختن</option><option>خرابی مواد</option><option>خطای آماده‌سازی</option><option>ریزش/شکستگی</option><option>اشتباه سفارش</option><option>نامشخص</option></select></div><div class="field full"><label>توضیحات</label><input id="opWasteNotes"></div><div class="full"><button class="btn btn-primary" onclick="opsSaveWaste()">ثبت ضایعات</button></div></div><div class="hint">اگر کل یک فاکتور چند آیتمی حذف شده، برای هر آیتم یک ردیف با همان تاریخ و شماره فاکتور ثبت کنید؛ در گزارش به‌صورت یک گروه نمایش داده می‌شود.</div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>فاکتور سپیدز</th><th>مورد</th><th>مقدار</th><th>علت</th><th>ارزش</th><th></th></tr></thead><tbody>${rows.map(w=>`<tr><td>${E(w.date)}</td><td>${w.invoiceNumber?`${E(w.invoiceNumber)}${groups[`${D(w.date)}|${w.invoiceNumber}`]>1?` <span class="badge">${F(groups[`${D(w.date)}|${w.invoiceNumber}`])} آیتم</span>`:''}`:'—'}</td><td>${E(w.type==='menu'?menu(w.itemId)?.name:ingredient(w.itemId)?.name)||'—'}</td><td>${F(w.quantity,3)}</td><td>${E(w.reason||'—')} ${w.known===false||w.causeKnown===false?'<span class="badge warn">نیازمند بررسی</span>':''}</td><td>${M(wasteValue(w))}</td><td><button class="btn btn-danger btn-sm" onclick="opsDeleteWaste('${w.id}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">ضایعاتی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function salesPane(){setTimeout(()=>{if(!$id('opSalesLines')?.children.length)opsAddSalesLine()},0);return `<div class="card"><div class="section-head"><div><h2>ثبت فروش آیتم‌های منو</h2></div><div class="pricing-actions"><button class="btn" type="button" onclick="document.getElementById('p2SalesExcel').click()">ورود فروش روزانه Excel</button><button class="btn btn-sm" type="button" onclick="RayoDownloadTemplate?.('salesDaily')">⬇ دانلود نمونه</button><input hidden id="p2SalesExcel" type="file" accept=".xlsx,.xls,.csv" onchange="p2ImportSalesExcel(event)"></div></div><div class="ops-grid"><div class="field"><label>از تاریخ</label><input id="opSalesFrom" data-jalali="1" value="${today()}"></div><div class="field"><label>تا تاریخ</label><input id="opSalesTo" data-jalali="1" value="${today()}"></div><div class="field"><label>مرجع / فایل سپیدز</label><input id="opSalesRef" placeholder="اختیاری"></div><div class="full"><div class="section-head"><h2>اقلام فروش</h2><button class="btn btn-sm" onclick="opsAddSalesLine()">+ آیتم</button></div><div id="opSalesLines"></div></div><div class="full toolbar"><div class="hint">جمع محاسباتی فروش دستی: <b id="opSalesCalculatedTotal">۰ تومان</b></div><button class="btn btn-primary" onclick="opsSaveSales()">ثبت فروش دوره</button></div></div><div class="hint">قیمت فروش هر آیتم هنگام ثبت، به‌عنوان Snapshot ذخیره می‌شود تا گزارش سود دوره بعداً با تغییر قیمت منو خراب نشود.</div></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>دوره</th><th>مرجع</th><th>تعداد آیتم</th><th>تعداد فروش</th><th>فروش تقریبی</th><th></th></tr></thead><tbody>${A(ops.inv.salesPeriods).filter(x=>x.status!=='void').slice().sort((a,b)=>dateCmp(D(b.to),D(a.to))).map(sp=>{const q=A(sp.lines).reduce((a,l)=>a+N(l.quantity),0),rev=A(sp.lines).reduce((a,l)=>a+N(l.quantity)*N(l.salePriceToman||menu(l.menuItemId)?.currentPriceToman),0);return`<tr><td>${E(sp.from)} تا ${E(sp.to)}</td><td>${E(sp.reference||'—')}</td><td>${F(A(sp.lines).length)}</td><td>${F(q)}</td><td>${M(rev)}</td><td><button class="btn btn-danger btn-sm" onclick="opsDeleteSales('${sp.id}')">حذف</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">فروشی ثبت نشده است.</td></tr>'}</tbody></table></div></div>${snappPaneCore()}`}
function stockPane(){setTimeout(()=>{if(!$id('opStockLines')?.children.length){const important=A(ops.pricing.ingredients).filter(i=>tracked(i.id)?.priority==='بالا').slice(0,8);(important.length?important:[ops.pricing.ingredients[0]].filter(Boolean)).forEach(i=>opsAddStockLine(i.id))}},0);return `<div class="card"><div class="section-head"><h2>انبارگردانی و ثبت موجودی واقعی</h2></div><div class="ops-grid"><div class="field"><label>تاریخ شمارش</label><input id="opStockDate" data-jalali="1" value="${today()}"></div><div class="full"><div class="section-head"><h2>مواد شمارش‌شده</h2><button class="btn btn-sm" onclick="opsAddStockLine()">+ ماده</button></div><div id="opStockLines"></div></div><div class="full"><button class="btn btn-primary" onclick="opsSaveStock()">ثبت شمارش و محاسبه مغایرت</button></div></div><div class="hint">مغایرت فقط در روزهایی قابل اندازه‌گیری است که موجودی واقعی شمارش شود. بین دو شمارش، «موجودی لحظه‌ای» مقدار تئوریک بر اساس آخرین شمارش، خرید، فروش و ضایعات است.</div></div>`}
function historyPane(){const all=[];for(const st of A(ops.inv.stocktakes)){for(const l of A(st.lines)){let calc;if(l.expected!==undefined&&l.variance!==undefined){calc={...l,date:st.date,ingredientId:l.ingredientId};if(!N(calc.periodUnitCostToman)){const c=periodPurchaseCost(l.ingredientId,D(l.baseDate||''),D(st.date));calc.periodUnitCostToman=N(c.unitCost);calc.unitCost=calc.periodUnitCostToman;calc.periodPurchaseQuantity=N(c.purchasedQty);calc.periodPurchaseValueToman=N(c.purchaseValueToman);calc.unitCostSource=c.source;calc.unitCostReferenceDate=c.referenceDate||'';calc.varianceValueToman=N(calc.variance)*calc.unitCost;calc.lossValueToman=N(calc.variance)<0?-N(calc.variance)*calc.unitCost:0}}else calc=positionAt(l.ingredientId,D(st.date),{excludeStocktakeId:st.id,actual:l.actual,allowSameBaseline:false});all.push({...calc,stocktakeId:st.id})}}all.sort((a,b)=>dateCmp(D(b.date),D(a.date)));const ids=[...new Set(all.map(x=>x.ingredientId))];if(!ops.filters.historyIngredient&&ids.length)ops.filters.historyIngredient=ids[0];const rows=all.filter(x=>!ops.filters.historyIngredient||x.ingredientId===ops.filters.historyIngredient);const latest=rows[0],prev=rows[1],improve=latest&&prev?Math.abs(N(prev.variance))-Math.abs(N(latest.variance)):null,max=Math.max(1,...rows.map(x=>Math.abs(N(x.variance))));return `<div class="card"><div class="toolbar"><div class="field"><label>ماده اولیه</label><select onchange="ops.filters.historyIngredient=this.value;renderView()"><option value="">همه مواد</option>${ids.map(i=>`<option value="${i}" ${ops.filters.historyIngredient===i?'selected':''}>${E(ingredient(i)?.name||i)}</option>`).join('')}</select></div></div></div>${latest?`<div class="grid grid-3"><div class="card kpi"><div class="label">آخرین مغایرت نامشخص</div><div class="value ${N(latest.variance)<0?'danger-text':''}">${F(latest.variance,3)}</div></div><div class="card kpi"><div class="label">خسارت مالی آخرین دوره</div><div class="value">${F(N(latest.lossValueToman)||0)}</div><div class="sub">تومان — ${E(latest.unitCostSource||'قیمت دوره')}</div></div><div class="card kpi"><div class="label">تغییر نسبت به دوره قبل</div><div class="value ${improve>=0?'positive':'danger-text'}">${improve===null?'—':`${improve>=0?'بهبود ': 'بدتر '} ${F(Math.abs(improve),3)}`}</div></div></div>`:''}<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>ماده</th><th>موجودی مبنا</th><th>ورود</th><th>مصرف فروش</th><th>ضایعات ثبت‌شده</th><th>مورد انتظار</th><th>واقعی</th><th>مغایرت کل قبل ضایعات</th><th>مغایرت نامشخص</th><th>خرید دوره</th><th>قیمت مبنای دوره</th><th>خسارت مغایرت</th><th>روند</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${E(x.date)}</td><td>${E(ingredient(x.ingredientId)?.name||x.ingredientId)}</td><td>${F(x.baseQuantity,3)}</td><td>${F(x.receipts,3)}</td><td>${F(x.salesConsumption,3)}</td><td>${F(x.recordedWaste,3)}</td><td>${F(x.expected,3)}</td><td>${F(x.actual,3)}</td><td>${F(x.grossVariance,3)}</td><td class="${N(x.variance)<0?'danger-text':'positive'}"><b>${F(x.variance,3)}</b></td><td>${M(x.periodPurchaseValueToman||0)}</td><td>${M(x.periodUnitCostToman||x.unitCost||0)}<br><small class="muted">${E(x.unitCostSource||'')}</small></td><td>${M(x.lossValueToman||0)}</td><td><div class="mini-trend"><span style="width:${Math.max(2,Math.abs(N(x.variance))/max*100)}%"></span></div></td></tr>`).join('')||'<tr><td colspan="14" class="empty">برای این ماده هنوز سابقه انبارگردانی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
async function saveInv(msg){await window.ivSaveData(false,msg);toast(msg)}
async function saveBoth(msg){await Promise.all([window.ivSaveData(false,msg),window.pcSaveData(false,msg)]);toast(msg)}
function addInvoiceLine(line={}){const ing=ingredient(line.ingredientId)||ops.pricing.ingredients[0],purchaseQty=N(line.purchaseQuantity??line.quantity),unitPrice=N(line.unitPrice);$id('opInvLines')?.insertAdjacentHTML('beforeend',`<div class="ops-line invoice-line"><select class="oli" onchange="opsRefreshInvoiceLine(this.parentElement)">${opts(ops.pricing.ingredients,'id',i=>`${i.code||''} | ${i.name} — خرید: ${i.purchaseUnit||'واحد'} / مصرف: ${i.recipeUnit||'واحد'}`,ing?.id||'')}</select><input class="olq" type="number" step="0.001" placeholder="تعداد خرید" value="${purchaseQty||''}" oninput="opsRefreshInvoiceLine(this.parentElement)"><input class="olp" type="number" placeholder="قیمت واحد خرید" value="${unitPrice||''}"><span class="olconvert muted"></span><button class="btn btn-danger btn-sm" onclick="this.parentElement.remove()">حذف</button></div>`);const row=$id('opInvLines')?.lastElementChild;if(row)refreshInvoiceLine(row)}
function refreshInvoiceLine(row){const i=ingredient(row.querySelector('.oli')?.value),q=N(row.querySelector('.olq')?.value),factor=N(i?.packageQuantity)||1;const s=row.querySelector('.olconvert');if(s)s.textContent=q?`${F(q*factor,3)} ${i?.recipeUnit||'واحد'} ورود انبار`:''}
async function saveInvoice(){try{const lines=[...document.querySelectorAll('#opInvLines .invoice-line')].map(r=>{const i=ingredient(r.querySelector('.oli').value),purchaseQuantity=N(r.querySelector('.olq').value),unitPrice=N(r.querySelector('.olp').value),factor=N(i?.packageQuantity)||1;return{ingredientId:i?.id||'',purchaseQuantity,quantity:purchaseQuantity,stockQuantity:purchaseQuantity*factor,unitPrice,purchaseUnit:i?.purchaseUnit||'',recipeUnit:i?.recipeUnit||'',packageQuantity:factor}}).filter(x=>x.ingredientId&&x.purchaseQuantity>0&&x.unitPrice>=0);if(!lines.length)throw Error('حداقل یک ردیف معتبر وارد کنید');const supplierId=$id('opInvSup').value,date=D($id('opInvDate').value),number=$id('opInvNo').value.trim(),discount=N($id('opInvDiscount').value),settlementStatus=$id('opInvSettlement').value,paymentMethod=$id('opInvPayMethod').value,paymentLocationId=$id('opInvPayLocation').value,notes=$id('opInvNotes').value;if(!supplierId||!date)throw Error('تأمین‌کننده و تاریخ الزامی است');let x=ops.editInvoiceId?ops.inv.purchaseInvoices.find(i=>i.id===ops.editInvoiceId):null,paidAmount=N($id('opInvPaid').value),linked=x?linkedPayments(x.id):0,total=invoiceTotal({lines,discount});if(settlementStatus==='unpaid'){if(linked>0)throw Error('برای این فاکتور پرداخت جداگانه ثبت شده است؛ ابتدا پرداخت‌ها را حذف کنید یا وضعیت را جزئی/تسویه‌شده بگذارید');paidAmount=0}else if(settlementStatus==='paid'){paidAmount=Math.max(0,total-linked);if(paidAmount>0&&!paymentLocationId)throw Error('برای فاکتور تسویه‌شده محل پرداخت را انتخاب کنید')}else{const totalPaid=paidAmount+linked;if(totalPaid<=0||totalPaid+0.5>=total)throw Error('برای تسویه جزئی، مبلغ پرداخت‌شده باید بیشتر از صفر و کمتر از جمع فاکتور باشد');if(paidAmount>0&&!paymentLocationId)throw Error('برای مبلغ پرداخت‌شده محل پرداخت را انتخاب کنید')}const paymentLocationNameSnapshot=paymentLocationId?paymentLocationName(paymentLocationId,''):'';const affected=new Set(A(x?.lines).map(l=>l.ingredientId));if(x){ops.inv.stockReceipts=ops.inv.stockReceipts.filter(r=>r.invoiceId!==x.id);ops.pricing.ingredientPriceHistory=A(ops.pricing.ingredientPriceHistory).filter(r=>r.invoiceId!==x.id);Object.assign(x,{date,supplierId,number,discount,paidAmount,paymentMethod,paymentLocationId,paymentLocationNameSnapshot,settlementStatus,notes,lines,updatedAt:new Date().toISOString()})}else{x={id:id('PINV'),date,supplierId,number,discount,paidAmount,paymentMethod,paymentLocationId,paymentLocationNameSnapshot,settlementStatus,notes,lines,createdAt:new Date().toISOString()};ops.inv.purchaseInvoices.push(x)}for(const l of lines){affected.add(l.ingredientId);ops.inv.stockReceipts.push({id:id('REC'),invoiceId:x.id,date,ingredientId:l.ingredientId,purchaseQuantity:l.purchaseQuantity,quantity:l.stockQuantity,unitPrice:l.unitPrice,purchaseUnit:l.purchaseUnit,recipeUnit:l.recipeUnit,locationId:ops.inv.settings?.mainLocationId||'LOC-MAIN',status:'pending'});const z=ingredient(l.ingredientId);if(z){z.lastPurchasePriceToman=l.unitPrice;z.latestPriceToman=l.unitPrice;z.lastPurchaseDate=date;ops.pricing.ingredientPriceHistory=A(ops.pricing.ingredientPriceHistory);ops.pricing.ingredientPriceHistory.push({id:id('IPH'),ingredientId:z.id,date,priceToman:l.unitPrice,source:'supplierInvoice',invoiceId:x.id,createdAt:new Date().toISOString()})}}refreshIngredientLatest([...affected]);x.paymentStatus=invoiceStatus(x);x.settlementStatus=settlementCode(x);ops.editInvoiceId='';await saveBoth('فاکتور خرید ثبت شد؛ دریافت کالا باید توسط انبار تأیید شود');renderView()}catch(e){window.RayoErrorLog?.capture?.(e,{source:'save-invoice'});toast(e.message||'ثبت فاکتور انجام نشد',true)}}

async function deleteInvoice(invoiceId){if(!confirm('فاکتور و ورودهای انبار وابسته حذف شود؟'))return;const x=ops.inv.purchaseInvoices.find(i=>i.id===invoiceId),affected=A(x?.lines).map(l=>l.ingredientId);ops.inv.purchaseInvoices=ops.inv.purchaseInvoices.filter(i=>i.id!==invoiceId);ops.inv.stockReceipts=ops.inv.stockReceipts.filter(r=>r.invoiceId!==invoiceId);ops.inv.supplierPayments=ops.inv.supplierPayments.filter(p=>p.invoiceId!==invoiceId);ops.pricing.ingredientPriceHistory=A(ops.pricing.ingredientPriceHistory).filter(r=>r.invoiceId!==invoiceId);refreshIngredientLatest(affected);await saveBoth(`حذف فاکتور ${x?.number||''}`);renderView()}
let paymentSaving=false,paymentPending=null;
async function savePayment(){if(paymentSaving)return;let before;try{const supplierId=$id('opPaySup').value,date=D($id('opPayDate').value),amount=N($id('opPayAmount').value),invoiceId=$id('opPayInvoice').value,method=$id('opPayMethod').value,paymentLocationId=$id('opPayLocation').value,reference=S($id('opPayRef').value),notes=$id('opPayNotes').value,direction=$id('opPayDirection')?.value||'payment',directionOption=paymentDirections(direction).find(x=>x.value===direction);if(!supplierId||!date||amount<=0||!reference)throw Error('طرف، تاریخ، مبلغ و شماره پیگیری/رسید الزامی است');if(!paymentLocationId)throw Error('محل پرداخت را انتخاب کنید');if(!directionOption)throw Error('جهت تسویه معتبر نیست');if(invoiceId&&!A(ops.inv.purchaseInvoices).some(x=>x.id===invoiceId&&x.supplierId===supplierId&&!['void','draft','pending'].includes(x.status)))throw Error('فاکتور معتبر متعلق به همین طرف انتخاب کنید');if(directionOption.effect==='receipt'&&invoiceId)throw Error('وصول طلب قبلی را بدون فاکتور خرید ثبت کنید');if(A(ops.inv.supplierPayments).some(x=>x.id!==ops.editPaymentId&&x.status!=='void'&&x.paymentLocationId===paymentLocationId&&S(x.reference)===reference))throw Error('این مرجع پرداخت قبلاً ثبت شده است؛ همان رکورد را ویرایش کنید');const data={supplierId,invoiceId,date,amount,method,paymentLocationId,paymentLocationNameSnapshot:paymentLocationName(paymentLocationId,''),reference,notes,direction,directionLabelSnapshot:directionOption.label,directionEffect:directionOption.effect},signature=JSON.stringify(data);if(paymentPending&&paymentPending.signature!==signature)throw Error('نتیجه ثبت قبلی نامشخص است؛ ابتدا صفحه را بازخوانی کنید');const requestId=paymentPending?.id||ops.editPaymentId||id('PAY');paymentPending={id:requestId,signature};before=JSON.parse(JSON.stringify(ops.inv));paymentSaving=true;let row=A(ops.inv.supplierPayments).find(x=>x.id===requestId);if(row)Object.assign(row,data,{updatedAt:new Date().toISOString()});else ops.inv.supplierPayments.push({id:requestId,requestId,...data,createdAt:new Date().toISOString()});await saveInv('تسویه طرف تجاری ثبت شد؛ هزینه / درآمد جدید ایجاد نشد');ops.editPaymentId='';paymentPending=null;renderView()}catch(e){if(before){Object.keys(ops.inv).forEach(k=>delete ops.inv[k]);Object.assign(ops.inv,before)}toast(e.message||'ثبت تسویه انجام نشد',true)}finally{paymentSaving=false}}

async function deletePayment(paymentId){if(!confirm('این پرداخت حذف شود؟'))return;ops.inv.supplierPayments=ops.inv.supplierPayments.filter(x=>x.id!==paymentId);await saveInv('پرداخت حذف شد');renderView()}
async function saveWaste(){try{const type=$id('opWasteType').value,itemId=$id('opWasteItem').value,quantity=N($id('opWasteQty').value),date=D($id('opWasteDate').value);if(!itemId||quantity<=0||!date)throw Error('تاریخ، مورد و مقدار معتبر الزامی است');ops.inv.wasteRecords.push({id:id('WST'),date,invoiceNumber:$id('opWasteInvoice').value.trim(),type,itemId,quantity,known:$id('opWasteKnown').value==='true',causeKnown:$id('opWasteKnown').value==='true',reason:$id('opWasteReason').value,notes:$id('opWasteNotes').value,createdAt:new Date().toISOString()});await saveInv('پرتی/ضایعات با موفقیت ثبت شد');renderView()}catch(e){toast(e.message||'ثبت ضایعات انجام نشد',true)}}
async function deleteWaste(wid){if(!confirm('این رکورد ضایعات حذف شود؟'))return;ops.inv.wasteRecords=ops.inv.wasteRecords.filter(x=>x.id!==wid);await saveInv('رکورد ضایعات حذف شد');renderView()}
function refreshSalesTotal(){let total=0;document.querySelectorAll('#opSalesLines .sales-line').forEach(r=>{const mid=r.querySelector('.osm')?.value,q=N(r.querySelector('.osq')?.value);total+=q*menuSalePrice(menu(mid))});const out=$id('opSalesCalculatedTotal');if(out)out.textContent=`${F(total)} تومان`}
