function addSalesLine(line={}){const m=menu(line.menuItemId)||ops.pricing.menuItems[0],q=N(line.quantity)||0,amount=q*menuSalePrice(m);$id('opSalesLines')?.insertAdjacentHTML('beforeend',`<div class="ops-line sales-line"><select class="osm" onchange="opsRefreshSalesLine(this.closest('.sales-line'))">${opts(ops.pricing.menuItems,'id',x=>`${x.code||''} | ${x.name}`,m?.id||'')}</select><input class="osq" type="number" step="1" placeholder="تعداد فروش (عدد/پرس)" value="${q||''}" oninput="opsRefreshSalesLine(this.closest('.sales-line'))"><div class="v105-line-amount"><small class="muted">مبلغ کل محاسباتی</small><br><b data-sale-amount>${amount?`${F(amount)} تومان`:'—'}</b></div><span></span><button class="btn btn-danger btn-sm" onclick="this.parentElement.remove();opsRefreshSalesTotal()">حذف</button></div>`);refreshSalesTotal()}
async function saveSales(){try{const from=D($id('opSalesFrom').value),to=D($id('opSalesTo').value),reference=$id('opSalesRef').value.trim(),lines=[...document.querySelectorAll('#opSalesLines .sales-line')].map(r=>{const menuItemId=r.querySelector('.osm').value,quantity=N(r.querySelector('.osq').value),m=menu(menuItemId);return{menuItemId,quantity,salePriceToman:menuSalePrice(m)}}).filter(x=>x.quantity>0);if(!from||!to||!lines.length)throw Error('بازه تاریخ و حداقل یک آیتم فروش الزامی است');ops.inv.salesPeriods.push({id:id('SALE'),from,to,reference,lines,createdAt:new Date().toISOString()});await saveInv('فروش دوره با موفقیت ثبت شد');renderView()}catch(e){toast(e.message||'ثبت فروش انجام نشد',true)}}

function snappMenuOptions(selected=''){return `<option value="">انتخاب کنید</option>`+A(ops.pricing?.menuItems).filter(x=>x.status!=='غیرفعال').slice().sort((a,b)=>S(a.name).localeCompare(S(b.name),'fa')).map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.code||'')} | ${E(x.name)}</option>`).join('')}
function snappRowCore(line={}){const q=N(line.quantity)||1,mid=S(line.menuItemId),amount=q*menuSalePrice(menu(mid));return `<div class="v1052-snapp-row" style="display:grid;grid-template-columns:minmax(180px,2fr) minmax(100px,1fr) minmax(150px,1fr) auto;gap:8px;align-items:end;margin-bottom:8px"><div class="field"><label>آیتم منو</label><select data-snapp-item onchange="opsRefreshSnappLine(this.closest('.v1052-snapp-row'))">${snappMenuOptions(mid)}</select></div><div class="field"><label>تعداد فروش (عدد)</label><input data-snapp-qty type="number" min="0" step="1" value="${q}" oninput="opsRefreshSnappLine(this.closest('.v1052-snapp-row'))"></div><div class="field"><label>مبلغ کل محاسباتی</label><div><b data-snapp-amount>${amount?`${F(amount)} تومان`:'—'}</b></div></div><button class="btn btn-danger btn-sm" type="button" onclick="this.closest('.v1052-snapp-row').remove();opsRefreshSnappTotal()">حذف</button></div>`}
function refreshSnappTotalCore(){let total=0;document.querySelectorAll('#opSnappLines .v1052-snapp-row').forEach(r=>{const mid=S(r.querySelector('[data-snapp-item]')?.value),q=N(r.querySelector('[data-snapp-qty]')?.value);total+=q*menuSalePrice(menu(mid))});const out=$id('opSnappCalculatedTotal');if(out)out.textContent=`${F(total)} تومان`}
function refreshSnappLineCore(row){if(!row)return;const mid=S(row.querySelector('[data-snapp-item]')?.value),q=N(row.querySelector('[data-snapp-qty]')?.value),amount=q*menuSalePrice(menu(mid));const out=row.querySelector('[data-snapp-amount]');if(out)out.textContent=amount?`${F(amount)} تومان`:'—';refreshSnappTotalCore()}
function addSnappLineCore(line={}){$id('opSnappLines')?.insertAdjacentHTML('beforeend',snappRowCore(line));refreshSnappTotalCore()}
function snappPaneCore(){const rows=A(ops.inv?.salesPeriods).filter(x=>x.status!=='void'&&(x.salesSource==='SNAPP'||x.source==='SNAPP')).slice().sort((a,b)=>D(b.to||b.date||b.from).localeCompare(D(a.to||a.date||a.from))).slice(0,60);return `<div class="card v1052-snapp-card"><div class="section-head"><div><h2>فروش اسنپ</h2><p class="muted">فروش اسنپ در خروجی سپیدز نیست. فروش را برای یک روز یا بازه وارد کنید تا مصرف رسپی آن از موجودی کم شود.</p></div><div class="pricing-actions"><button class="btn" type="button" onclick="document.getElementById('opSnappExcel').click()">ورود فروش اسنپ Excel</button><button class="btn btn-sm" type="button" onclick="RayoDownloadTemplate?.('salesDaily')">⬇ دانلود نمونه</button><input hidden id="opSnappExcel" type="file" accept=".xlsx,.xls,.csv" onchange="opsImportSnappExcel(event)"></div></div><div class="ops-grid"><div class="field"><label>از تاریخ</label><input id="opSnappFrom" data-jalali="1" value="${E(today())}"></div><div class="field"><label>تا تاریخ</label><input id="opSnappTo" data-jalali="1" value="${E(today())}"></div><div class="full"><div class="hint">برای کنترل دقیق روزانه، در Excel ستون تاریخ داشته باشید؛ در این حالت هر روز جداگانه ثبت می‌شود.</div></div><div class="full"><div class="section-head"><h2>اقلام فروش اسنپ</h2><button class="btn btn-sm" type="button" onclick="opsAddSnappLine()">+ آیتم</button></div><div id="opSnappLines">${snappRowCore()}${snappRowCore()}${snappRowCore()}</div></div><div class="full toolbar"><div class="hint">جمع محاسباتی فروش اسنپ: <b id="opSnappCalculatedTotal">۰ تومان</b></div><button class="btn btn-primary" type="button" onclick="opsSaveSnappSales()">ثبت فروش اسنپ و اعمال در موجودی</button></div></div></div><div class="card"><div class="section-head"><h2>آخرین فروش‌های اسنپ ثبت‌شده</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>بازه</th><th>تعداد آیتم</th><th>جمع تعداد</th><th>مبلغ</th><th></th></tr></thead><tbody>${rows.map(x=>{const amt=A(x.lines).reduce((a,l)=>a+(N(l.saleAmountToman)||N(l.quantity)*N(l.salePriceToman||menuSalePrice(menu(l.menuItemId)))),0);return `<tr><td>${E(x.from||x.date)}${D(x.to||x.date)!==D(x.from||x.date)?` تا ${E(x.to||x.date)}`:''}</td><td>${F(A(x.lines).length)}</td><td>${F(A(x.lines).reduce((a,l)=>a+N(l.quantity),0))}</td><td>${M(amt)}</td><td><button class="btn btn-danger btn-sm" onclick="opsVoidSnapp('${E(x.id)}')">ابطال</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">فروش اسنپی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function rangeOverlapCore(a1,a2,b1,b2){a1=D(a1);a2=D(a2)||a1;b1=D(b1);b2=D(b2)||b1;return !!a1&&!!b1&&a1<=b2&&b1<=a2}
async function saveSnappSalesCore(){try{const from=D($id('opSnappFrom')?.value),to=D($id('opSnappTo')?.value);if(!from||!to)throw Error('از تاریخ و تا تاریخ الزامی است');if(from>to)throw Error('«از تاریخ» نمی‌تواند بعد از «تا تاریخ» باشد');if(A(ops.inv.salesPeriods).some(x=>x.status!=='void'&&(x.salesSource==='SNAPP'||x.source==='SNAPP')&&rangeOverlapCore(from,to,x.from||x.date,x.to||x.date)))throw Error('برای تمام یا بخشی از این بازه فروش اسنپ قبلاً ثبت شده است. ابتدا رکورد قبلی را ابطال کنید.');const by=new Map;document.querySelectorAll('#opSnappLines .v1052-snapp-row').forEach(r=>{const mid=S(r.querySelector('[data-snapp-item]')?.value),q=N(r.querySelector('[data-snapp-qty]')?.value);if(mid&&q>0)by.set(mid,(by.get(mid)||0)+q)});const lines=[...by].map(([menuItemId,quantity])=>{const salePriceToman=menuSalePrice(menu(menuItemId));return{menuItemId,quantity,salePriceToman,saleAmountToman:quantity*salePriceToman}});if(!lines.length)throw Error('حداقل یک آیتم و تعداد معتبر وارد کنید');ops.inv.salesPeriods.push({id:id('SNAPP'),from,to,date:from===to?from:'',reference:'فروش اسنپ دستی',salesSource:'SNAPP',source:'SNAPP',lines,status:'posted',createdAt:new Date().toISOString(),createdBy:sessionStorage.getItem('rayo_admin_user')||'admin'});await saveInv('فروش اسنپ ثبت شد و در موجودی اثر می‌گذارد');renderView()}catch(e){window.RayoErrorLog?.capture?.(e,{source:'snapp-manual'});toast(e.message||'ثبت فروش اسنپ انجام نشد',true)}}
async function importSnappExcelCore(e){const file=e?.target?.files?.[0];if(e?.target)e.target.value='';if(!file)return;try{if(!window.RayoExcel?.readBest)throw Error('ماژول Excel آماده نیست');const from=D($id('opSnappFrom')?.value)||today(),to=D($id('opSnappTo')?.value)||from;if(from>to)throw Error('بازه تاریخ نامعتبر است');const spec={date:{aliases:['تاریخ','تاریخ فروش','روز']},code:{aliases:['کد آیتم','کد کالا','کد'],required:true,weight:4},name:{aliases:['نام آیتم','نام کالا','شرح']},quantity:{aliases:['تعداد فروش','مقدار فروش','تعداد','qty'],required:true,weight:4},amount:{aliases:['مبلغ فروش','جمع مبلغ','فروش']}};const t=await RayoExcel.readBest(file,spec),groups=new Map,norm=window.RayoExcel.norm||((x)=>S(x).toLowerCase());let skipped=0,outRange=0,noDate=0;for(const row of t.data){const code=S(t.get(row,'code')),name=S(t.get(row,'name')),m=A(ops.pricing.menuItems).find(x=>S(x.code)===code)||A(ops.pricing.menuItems).find(x=>name&&norm(x.name)===norm(name)),q=N(t.get(row,'quantity'));if(!m||q<=0){skipped++;continue}let date=D(t.get(row,'date'));if(!date){if(from===to)date=from;else{noDate++;continue}}if(date<from||date>to){outRange++;continue}const amount=N(t.get(row,'amount')),g=groups.get(date)||new Map,old=g.get(m.id)||{menuItemId:m.id,quantity:0,saleAmountToman:0};old.quantity+=q;old.saleAmountToman+=amount;g.set(m.id,old);groups.set(date,g)}if(!groups.size)throw Error(noDate?'در فایل برای بازه چندروزه ستون تاریخ معتبر پیدا نشد. ستون «تاریخ» را اضافه کنید.':'ردیف قابل ثبت در بازه انتخابی پیدا نشد');let addedDays=0,addedLines=0,duplicateDays=0;for(const [date,map] of groups){if(A(ops.inv.salesPeriods).some(x=>x.status!=='void'&&(x.salesSource==='SNAPP'||x.source==='SNAPP')&&rangeOverlapCore(date,date,x.from||x.date,x.to||x.date))){duplicateDays++;continue}const lines=[...map.values()].map(l=>{const salePriceToman=l.saleAmountToman>0?l.saleAmountToman/l.quantity:menuSalePrice(menu(l.menuItemId));return{...l,salePriceToman,saleAmountToman:l.saleAmountToman>0?l.saleAmountToman:l.quantity*salePriceToman,date}});ops.inv.salesPeriods.push({id:id('SNAPP-XLS'),from:date,to:date,date,reference:`Excel Snapp: ${file.name}`,salesSource:'SNAPP',source:'SNAPP',sourceFile:file.name,lines,status:'posted',createdAt:new Date().toISOString(),createdBy:sessionStorage.getItem('rayo_admin_user')||'admin'});addedDays++;addedLines+=lines.length}if(!addedDays)throw Error('همه روزهای فایل قبلاً ثبت شده‌اند یا قابل استفاده نیستند');await saveInv(`${addedLines} ردیف فروش اسنپ در ${addedDays} روز ثبت شد${duplicateDays?`؛ ${duplicateDays} روز تکراری رد شد`:''}${skipped?`؛ ${skipped} ردیف نامطابق رد شد`:''}${outRange?`؛ ${outRange} ردیف خارج از بازه نادیده گرفته شد`:''}`);renderView()}catch(err){window.RayoErrorLog?.capture?.(err,{source:'snapp-excel-import'});toast(err.message||'ورود Excel فروش اسنپ انجام نشد',true)}}
async function voidSnappCore(sid){const x=A(ops.inv.salesPeriods).find(r=>r.id===sid);if(!x||!confirm('ثبت فروش اسنپ ابطال شود؟'))return;x.status='void';x.voidedAt=new Date().toISOString();x.voidedBy=sessionStorage.getItem('rayo_admin_user')||'admin';await saveInv('ثبت فروش اسنپ ابطال شد');renderView()}

async function deleteSales(sid){if(!confirm('این دوره فروش حذف شود؟'))return;ops.inv.salesPeriods=ops.inv.salesPeriods.filter(x=>x.id!==sid);await saveInv('دوره فروش حذف شد');renderView()}
function addStockLine(ingredientId=''){const i=ingredient(ingredientId)||ops.pricing.ingredients[0];$id('opStockLines')?.insertAdjacentHTML('beforeend',`<div class="ops-line stock-line"><select class="osi">${opts(ops.pricing.ingredients,'id',x=>`${x.code||''} | ${x.name} — ${x.recipeUnit||'واحد'}`,i?.id||'')}</select><input class="osa" type="number" step="0.001" placeholder="موجودی واقعی"><span></span><span></span><button class="btn btn-danger btn-sm" onclick="this.parentElement.remove()">حذف</button></div>`)}
async function saveStock(){try{const date=D($id('opStockDate').value),raw=[...document.querySelectorAll('#opStockLines .stock-line')].map(r=>({ingredientId:r.querySelector('.osi').value,actual:N(r.querySelector('.osa').value),raw:r.querySelector('.osa').value})).filter(x=>String(x.raw).trim()!=='');if(!date||!raw.length)throw Error('تاریخ و حداقل یک موجودی واقعی الزامی است');const stocktakeId=id('ST'),lines=raw.map(l=>{const p=positionAt(l.ingredientId,date,{excludeStocktakeId:stocktakeId,actual:l.actual,allowSameBaseline:false});return{ingredientId:l.ingredientId,actual:l.actual,baseDate:p.baseDate,baseQuantity:p.baseQuantity,baseSource:p.baseSource,receipts:p.receipts,salesConsumption:p.salesConsumption,recordedWaste:p.recordedWaste,expectedBeforeWaste:p.expectedBeforeWaste,expected:p.expected,grossVariance:p.grossVariance,variance:p.variance,unitCost:p.unitCost,periodUnitCostToman:p.periodUnitCostToman,periodPurchaseQuantity:p.periodPurchaseQuantity,periodPurchaseValueToman:p.periodPurchaseValueToman,unitCostSource:p.unitCostSource,unitCostReferenceDate:p.unitCostReferenceDate,costSnapshotAt:new Date().toISOString(),varianceValueToman:p.varianceValueToman,lossValueToman:p.lossValueToman}});ops.inv.stocktakes.push({id:stocktakeId,date,lines,createdAt:new Date().toISOString()});await saveInv('انبارگردانی و مغایرت با موفقیت ثبت شد');ops.tab='history';renderView()}catch(e){window.RayoErrorLog?.capture?.(e,{source:'save-stocktake'});toast(e.message||'ثبت انبارگردانی انجام نشد',true)}}
function editStockControl(ingredientId){const i=ingredient(ingredientId),c=tracked(ingredientId)||{};$id('modalTitle').textContent=`تنظیم موجودی و سفارش — ${i?.name||''}`;$id('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>موجودی اولیه (${E(i?.recipeUnit||'واحد')})</label><input id="oscInitial" type="number" step="0.001" value="${N(c.initialStock)}"></div><div class="field"><label>تاریخ موجودی اولیه</label><input id="oscInitialDate" data-jalali="1" value="${E(c.initialStockDate||'')}"></div><div class="field"><label>نقطه سفارش (${E(i?.recipeUnit||'واحد')})</label><input id="oscReorder" type="number" step="0.001" value="${N(c.reorderPoint)}"></div><div class="field"><label>موجودی هدف</label><input id="oscTarget" type="number" step="0.001" value="${N(c.targetStock)}"></div><div class="field"><label>اهمیت مغایرت‌گیری</label><select id="oscPriority">${['بالا','متوسط','عادی'].map(x=>`<option ${x===(c.priority||'عادی')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>تأمین‌کننده اصلی</label><select id="oscSupplier"><option value="">—</option>${opts(ops.sup.suppliers,'id',s=>supplierName(s),c.supplierId||'')}</select></div><div class="field full"><label>توضیحات</label><textarea id="oscNotes">${E(c.notes||'')}</textarea></div></div>`;$id('modalFoot').innerHTML=`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="opsSaveStockControl('${ingredientId}')">ذخیره</button>`;$id('modalBackdrop').classList.add('open')}
async function saveStockControl(ingredientId){let c=tracked(ingredientId);if(!c){c={id:id('TRACK'),ingredientId};ops.inv.trackedIngredients.push(c)}Object.assign(c,{enabled:true,initialStock:N($id('oscInitial').value),initialStockDate:D($id('oscInitialDate').value),reorderPoint:N($id('oscReorder').value),targetStock:N($id('oscTarget').value),priority:$id('oscPriority').value,supplierId:$id('oscSupplier').value,notes:$id('oscNotes').value});await saveInv('تنظیم موجودی و نقطه سفارش ذخیره شد');closeModal();renderView()}
function install(){if(typeof views==='undefined'||typeof titles==='undefined')return setTimeout(install,80);titles.inventory='انبار و کنترل مصرف';views.inventory=opsView;Object.assign(window,{RayoOpsAnalytics:{positionAt,currentPosition,invoiceTotal,invoicePaid,invoiceStatus,supplierAccount,wasteValue,ingredientUnitCost,menuUnitCost,periodPurchaseCost},ops,opsTab:t=>{ops.tab=t;const u=new URL(location.href);u.searchParams.set('tab',t);history.replaceState({},'',u);renderView()},opsAddInvoiceLine:addInvoiceLine,opsRefreshInvoiceLine:refreshInvoiceLine,opsSaveInvoice:saveInvoice,opsEditInvoice:x=>{ops.editInvoiceId=x;ops.tab='invoice';renderView()},opsCancelInvoiceEdit:()=>{ops.editInvoiceId='';renderView()},opsDeleteInvoice:deleteInvoice,opsSavePayment:savePayment,opsEditPayment:x=>{ops.editPaymentId=x;ops.tab='payment';renderView()},opsCancelPaymentEdit:()=>{ops.editPaymentId='';renderView()},opsDeletePayment:deletePayment,opsWasteType:()=>{$id('opWasteItem').innerHTML=opts($id('opWasteType').value==='menu'?ops.pricing.menuItems:ops.pricing.ingredients)},opsSaveWaste:saveWaste,opsDeleteWaste:deleteWaste,opsAddSalesLine:addSalesLine,opsRefreshSalesLine:refreshSalesLine,opsRefreshSalesTotal:refreshSalesTotal,opsSaveSales:saveSales,opsDeleteSales:deleteSales,opsAddSnappLine:addSnappLineCore,opsRefreshSnappLine:refreshSnappLineCore,opsRefreshSnappTotal:refreshSnappTotalCore,opsSaveSnappSales:saveSnappSalesCore,opsImportSnappExcel:importSnappExcelCore,opsVoidSnapp:voidSnappCore,opsAddStockLine:addStockLine,opsSaveStock:saveStock,opsEditStockControl:editStockControl,opsSaveStockControl:saveStockControl});setTimeout(load,0)}
